 41 |         public async Task<(List<PenaltyEventData> NewEvents, List<ResolvedEventData> ResolvedEvents, List<CanceledEventData> CanceledEvents)> ProcessAsync(IEnumerable<PenaltyRuleDefinition> matchedRules)
 42 |         {
 43 |             var newEvents = new List<PenaltyEventData>();
 44 |             // 这种简单处理器通常只对应一个规则
 45 |             var rule = matchedRules.FirstOrDefault();
 46 |             if (rule == null)
 47 |             {
 48 |                 return (newEvents, new List<ResolvedEventData>(), new List<CanceledEventData>());
 49 |             }
 50 | 
 51 | 
 52 |             try
 53 |             {         
 54 |                 var allOslps = await UnitWork.Find<OSLP>(null)
 55 |                                        .ToListAsync();
 56 |                 var slpCodeToNameMap = allOslps
 57 |                     .ToDictionary(
 58 |                         x => x.SlpCode,
 59 |                         x => x.SlpName
 60 |                     );
 61 |                 // 排除售后
 62 |                 //var csOrders = UnitWork.Find<sale_ordr>(x => x.U_ERPFrom == "4" && x.sbo_id == Define.SBO_ID).Select(x => x.DocEntry.Value).ToHashSet();
 63 |                 //首先要找到已结算的单据，已结算的单据退货，才需要重新关联新单据
 64 |                 //U_DevEntry 为关联的要退的订单号，U_New_OrdrID为关联的新订单号,
 65 |                 //若 U_New_OrdrID 没有值，且价格>0的物料全部退完，则说明这个单里的有价物料全退掉了，要计算罚息
 66 |                 //罚息基础金额 = 订单中价格=0的物料的 sum(DelivrdQty * LastPurPrc)
 67 |                 //若 U_New_OrdrID 有值，则说明这个单是空退, 无实际退货，只是将单据物料关联在新的 U_New_OrdrID 订单上 不用罚息
 68 |                 var returnItems = await (from r1 in UnitWork.Find<RIN1>(null)
 69 |                                             join r in UnitWork.Find<ORIN>(null) on r1.DocEntry equals r.DocEntry
 70 |                                             join m in UnitWork.Find<OITM>(null) on r1.ItemCode equals m.ItemCode
 71 |                                             where r.CANCELED == "N" && (r.U_New_ORDRID == null || r.U_New_ORDRID == "")
 72 |                                             select new { r.DocEntry, r.U_New_ORDRID, r1.ItemCode, r1.Price, r.U_DevEntry, r1.Quantity, r1.StockValue, m.LastPurPrc, r.CreateDate, r1.BaseEntry, r1.BaseType }).ToListAsync();
 73 | 
 74 |                 // U_DevEntry 为空时，通过 RIN1 → INV1 → DLN1 回溯原始订单号
 75 |                 var nullDevEntryItems = returnItems.Where(x => string.IsNullOrEmpty(x.U_DevEntry) && x.DocEntry.HasValue && x.BaseEntry.HasValue).ToList();
 76 |                 var resolvedDevEntryMap = new Dictionary<int, int>(); // ORIN.DocEntry → 原始ORDR.DocEntry
 77 |                 if (nullDevEntryItems.Any())
 78 |                 {
 79 |                     // 提取回溯所需数据：(ORIN.DocEntry, RIN1.BaseEntry, RIN1.BaseType)
 80 |                     var traceItems = nullDevEntryItems
 81 |                         .Select(x => (OrinDocEntry: x.DocEntry.Value, BaseEntry: x.BaseEntry.Value, BaseType: x.BaseType ?? 0))
 82 |                         .Distinct()
 83 |                         .ToList();
 84 |                     resolvedDevEntryMap = await ResolveOrderDocEntryFromReturnChainAsync(traceItems);
 85 |                 }
 86 | 
 87 |                 // 合并：有 U_DevEntry 的直接用，没有的用回溯结果
 88 |                 var returnItemsWithDevEntry = returnItems.Select(x => new
 89 |                 {
 90 |                     x.DocEntry, x.U_New_ORDRID, x.ItemCode, x.Price, x.Quantity, x.StockValue, x.LastPurPrc, x.CreateDate,
 91 |                     ResolvedDevEntry = !string.IsNullOrEmpty(x.U_DevEntry)
 92 |                         ? (int.TryParse(x.U_DevEntry, out var parsed) ? parsed : 0)
 93 |                         : (x.DocEntry.HasValue && resolvedDevEntryMap.TryGetValue(x.DocEntry.Value, out var resolved) ? resolved : 0)
 94 |                 }).Where(x => x.ResolvedDevEntry > 0 
 95 |                 //&& !csOrders.Contains(x.ResolvedDevEntry)
 96 |                 ).ToList();
 97 | 
 98 |                 var returnProducts = returnItemsWithDevEntry.Where(m => m.Price > 0).ToList();
 99 |                 var hadPenaltyOrdrs = (await (from pd in UnitWork.Find<PenaltyRuleDefinition>(null)
100 |                                               join r in UnitWork.Find<PenaltyEvent>(null) on pd.Id equals r.RuleDefinitionId
101 |                                               where pd.RuleHandlerCode == HandlerCode
102 |                                               select Convert.ToInt32(r.TriggerDocEntry)).ToListAsync()).ToHashSet();
103 | 
104 |                 var returnProductsInFilter = returnProducts
105 |                     .Where(x => !hadPenaltyOrdrs.Contains(x.ResolvedDevEntry))
106 |                     .Select(x => new { x.DocEntry, x.CreateDate, x.Quantity, x.ItemCode, x.Price, U_DevEntry = x.ResolvedDevEntry })
107 |                     .ToList();
108 |                 var returnOrdrDocEntrys = returnProductsInFilter.Select(x => x.U_DevEntry).Distinct().ToList();
109 | 
110 |                 var delivrdItems = await (from r1 in UnitWork.Find<RDR1>(null)
111 |                                              join r in UnitWork.Find<ORDR>(null) on r1.DocEntry equals r.DocEntry
112 |                                              join m in UnitWork.Find<OITM>(null) on r1.ItemCode equals m.ItemCode
113 |                                              where
114 |                                                 r.CANCELED == "N" && r.DocStatus == "C" && r1.DelivrdQty > 0 && r1.LineStatus == "C" && r1.OpenQty == 0 && m.InvntItem == "Y"
115 |                                                 &&  returnOrdrDocEntrys.Contains(r.DocEntry)
116 |                                              select new { r.DocEntry, r1.LineNum, r1.ItemCode, r1.DelivrdQty, r1.Price,m.ManSerNum, m.ManBtchNum ,m.LastPurPrc,r.SlpCode}
117 |                 ).ToListAsync();
118 |                 //delivrdItems = delivrdItems.Where( r=> !csOrders.Contains(r.DocEntry)).ToList();
119 |                 var delivrdProducts = delivrdItems.Where(x => x.Price > 0).ToList();
120 | 
121 |                 var delivrdProductsLookUp = delivrdProducts.ToLookup(x => x.DocEntry);
122 |                 foreach (var group in returnProductsInFilter.GroupBy(x => x.U_DevEntry))
123 |                 {
124 |                     var thisOrdrReturnItems = group.GroupBy(x => x.ItemCode).Select(x => new { ItemCode = x.Key, TotalQty = x.Sum(s => s.Quantity) }).ToDictionary(k => k.ItemCode, v => v.TotalQty);
125 |                     var delivrdItemsInThisOrdr = delivrdProductsLookUp[group.Key].GroupBy(x=>x.ItemCode).Select(x=> new { ItemCode = x.Key, TotalQty = x.Sum(s=>s.DelivrdQty) }).ToDictionary(k=>k.ItemCode,v=>v.TotalQty);
126 |                     //遍历订单中所有有价物料，检查每个物料是否都已退完
127 |                     if( delivrdItemsInThisOrdr.All(x=> x.Value == (thisOrdrReturnItems.TryGetValue(x.Key,out var returnedQty) ? returnedQty : 0 )))
128 |                     {
129 |                         // 退货单中 Price=0 的物料，按ItemCode汇总已退数量（针对当前原始订单）
130 |                         var returnedZeroPriceQtyByItem = returnItemsWithDevEntry
131 |                             .Where(x => x.Price == 0 && x.ResolvedDevEntry == group.Key)
132 |                             .GroupBy(x => x.ItemCode)
133 |                             .ToDictionary(g => g.Key, g => g.Sum(s => s.Quantity));
134 |                         // 未退的 Price=0 物料成本 = sum(未退数量 * LastPurPrc)
135 |                         var fixedPenaltyAmount = delivrdItems
136 |                             .Where(x => x.Price == 0 && x.DocEntry == group.Key)
137 |                             .GroupBy(x => x.ItemCode)
138 |                             .Sum(g =>
139 |                             {
140 |                                 var totalDelivrdQty = g.Sum(s => s.DelivrdQty);
141 |                                 returnedZeroPriceQtyByItem.TryGetValue(g.Key, out var returnedQty);
142 |                                 var unreturnedQty = totalDelivrdQty - (returnedQty ?? 0);
143 |                                 return unreturnedQty > 0 ? unreturnedQty * g.First().LastPurPrc : (decimal?)0;
144 |                             });
145 |                         var slpCode = delivrdItems.FirstOrDefault(x => x.Price == 0 && x.DocEntry == group.Key)?.SlpCode;
146 |                         
147 |                         if(fixedPenaltyAmount.HasValue && fixedPenaltyAmount != 0)
148 |                         {
149 |                             var PenaltyEvent = new PenaltyEventData
150 |                             {
151 |                                 RuleDefinitionId = rule.Id,
152 |                                 SlpCode = slpCode,
153 |                                 SlpName = slpCodeToNameMap[slpCode.Value],
154 |                                 TriggerDocType = "ORDR",
155 |                                 TriggerDocEntry = group.Key.ToString(),
156 |                                 SEDocEntry = group.Key, 
157 |                                 PenaltyBaseAmount = fixedPenaltyAmount.Value,
158 |                                 TriggerEventDate = group.OrderByDescending(x => x.CreateDate).First().CreateDate,
159 |                                 PenaltyStartDate = group.OrderByDescending(x => x.CreateDate).First().CreateDate,
160 |                             };
161 |                             newEvents.Add(PenaltyEvent);
162 |                         }
163 |                     }
164 |                 }
165 |             }
166 |             catch (Exception ex)
167 |             {
168 |                 LogHelper.Error(ex, "处理退货未关联新单据处理器失败",nameof(ReturnUnRelNewOrderProcessor),nameof(ProcessAsync));
169 |             }
170 |             return (newEvents, new List<ResolvedEventData>(), new List<CanceledEventData>());
171 |         }

